The json is cleaner here imo because the fields of the model may be more complex than just strings (eg: maps, and slices of interfaces). Concatenating those would be more verbose and require more logic when we add/remove fields:
```
func concatenateFields(m Model) string {
	var parts []string

	fields := []stringm.OriginalModel, m.System}
	parts = append(parts, fields...)
	parts = append(parts, m.AdapterPaths...)

	var optionKeys []string
	for k := range m.Options {
		optionKeys = append(optionKeys, k)
	}
	sort.Strings(optionKeys)

	for _, key := range optionKeys {
		valStr, _ := json.Marshal(m.Options[key])
		keyValConcat := key + ":" + string(valStr)
		parts = append(parts, keyValConcat)
	}

	for _, emb := range m.Embeddings {
		parts = append(parts, emb.String())
	}

	return strings.Join(parts, "")
}
```

